let _searchTimer = null;
var _apiCallTimes = [];
var _fdsSortCol = null;
var _fdsSortDir = null;
var _fdsSortTimer = null;
try { _fdsSortCol = localStorage.getItem('fds_sort_col') || null; _fdsSortDir = localStorage.getItem('fds_sort_dir') || null; } catch(e) {}
var _RL_WINDOW = 2200;
var _RL_MAX = 3;

var _fdsAdRefreshCount = 0;
var _FDS_AD_REFRESH_EVERY = 7;

function _showDebounceBar(ms) {
    var wrap = document.getElementById('debounce-bar-wrap');
    var bar = document.getElementById('debounce-bar');
    if (wrap && bar) {
        wrap.style.opacity = '1';
        bar.style.transition = 'none';
        bar.style.transform = 'scaleX(1)';
        void bar.offsetWidth;
        bar.style.transition = 'transform ' + ms + 'ms linear';
        bar.style.transform = 'scaleX(0)';
    }
}

function _checkClientRateLimit() {
    var now = Date.now();
    _apiCallTimes = _apiCallTimes.filter(function(t) { return now - t < _RL_WINDOW; });
    if (_apiCallTimes.length >= _RL_MAX) {
        return _apiCallTimes[0] + _RL_WINDOW - now;
    }
    return 0;
}

function debounceSearch() {
    clearTimeout(_searchTimer);
    _searchTimer = setTimeout(doSearch, 700);
    _showDebounceBar(700);
}

document.addEventListener('transitionend', function(e) {
    if (e.target && e.target.id === 'debounce-bar') {
        var wrap = document.getElementById('debounce-bar-wrap');
        if (wrap) wrap.style.opacity = '0';
    }
});

function clearSearch() {
    ['character_name', 'category', 'start_up', 'start_up_op', 'recovery', 'recovery_op',
     'hit', 'hit_op', 'block', 'block_op'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.value = '';
    });
    var lang = document.getElementById('language').value;
    try{localStorage.setItem('fds_cleared','1');localStorage.removeItem('fds_sort_col');localStorage.removeItem('fds_sort_dir');localStorage.removeItem('fds_sys_tag_filter');}catch(e){}
    window.location.href = '/?lang=' + encodeURIComponent(lang);
    return false;
}
function _updateFrameInputStyles() {
    ['start_up', 'recovery', 'hit', 'block'].forEach(function(id) {
        var el = document.getElementById(id);
        if (!el) return;
        if (el.value) {
            el.style.backgroundColor = 'var(--fds-input-active-bg)';
            el.style.color = 'var(--fds-active-text)';
        } else {
            el.style.backgroundColor = '';
            el.style.color = '';
        }
    });
}
function onChangeStartUp() {
    const start_up_op = document.getElementById("start_up_op").value;
    const start_up = document.getElementById("start_up").value;
    if (start_up_op && !start_up) {
        $("#start_up_op").find("option").eq(0).attr("selected", "selected");
    }
    _updateFrameInputStyles();
}
function onChangeRecovery() {
    const recovery_op = document.getElementById("recovery_op").value;
    const recovery = document.getElementById("recovery").value;
    if (recovery_op && !recovery) {
        $("#recovery_op").find("option").eq(0).attr("selected", "selected");
    }
    _updateFrameInputStyles();
}
function onChangeHit() {
    const hit_op = document.getElementById("hit_op").value;
    const hit = document.getElementById("hit").value;
    if (hit_op && !hit) {
        $("#hit_op").find("option").eq(0).attr("selected", "selected");
    }
    _updateFrameInputStyles();
}
function onChangeBlock() {
    const block_op = document.getElementById("block_op").value;
    const block = document.getElementById("block").value;
    if (block_op && !block) {
        $("#block_op").find("option").eq(0).attr("selected", "selected");
    }
    _updateFrameInputStyles();
}
document.addEventListener('DOMContentLoaded', _updateFrameInputStyles);
function doSearch(pageNo, scrollTop, noScroll, skipAdCount) {
    const lang = document.getElementById("language").value;
    const category = document.getElementById("category").value;
    const character_name = document.getElementById("character_name").value;
    const start_up_op = document.getElementById("start_up_op").value;
    const start_up = document.getElementById("start_up").value;
    const recovery_op = document.getElementById("recovery_op").value;
    const recovery = document.getElementById("recovery").value;
    const hit_op = document.getElementById("hit_op").value;
    const hit = document.getElementById("hit").value;
    const block_op = document.getElementById("block_op").value;
    const block = document.getElementById("block").value;
    let params
    if (start_up_op && !start_up) {
        return;
    }
    if (recovery_op && !recovery) {
        return;
    }
    if (hit_op && !hit) {
        return;
    }
    if (block_op && !block) {
        return;
    }


    if (lang) {
        params = "lang=" + encodeURIComponent(lang);
    }
    if (character_name) {
        params = params + "&character_name=" + encodeURIComponent(character_name);
    }
    if (category) {
        params = params + "&category=" + encodeURIComponent(category);
    }
    if (start_up) {
        if (start_up_op) {
            params = params + "&start_up_op=" + encodeURIComponent(start_up_op);
        } else {
            params = params + "&start_up_op=" + encodeURIComponent("=");
        }
        params = params + "&start_up=" + encodeURIComponent(start_up);
    }
    if (recovery) {
        if (recovery_op) {
            params = params + "&recovery_op=" + encodeURIComponent(recovery_op);
        } else {
            params = params + "&recovery_op=" + encodeURIComponent("=");
        }
        params = params + "&recovery=" + encodeURIComponent(recovery);
    }
    if (hit) {
        if (hit_op) {
            params = params + "&hit_op=" + encodeURIComponent(hit_op);
        } else {
            params = params + "&hit_op=" + encodeURIComponent("=");
        }
        params = params + "&hit=" + encodeURIComponent(hit);
    }
    if (block) {
        if (block_op) {
            params = params + "&block_op=" + encodeURIComponent(block_op);
        } else {
            params = params + "&block_op=" + encodeURIComponent("=");
        }
        params = params + "&block=" + encodeURIComponent(block);
    }
    var newUrl = params ? '/?' + params : '/';

    // Language change → full reload so char/cat selects are re-rendered by server
    if (_fdsCurrentLang && lang !== _fdsCurrentLang) {
        window.location.href = newUrl;
        return false;
    }

    // AJAX DOM replacement
    _updateCondStyles();
    var ua = (document.body && document.body.dataset.ua) || 'pc';
    if (window._listMode && ua === 'mobile') ua = 'mobile_list';
    if (window._listMode) {
        document.querySelectorAll('dialog[id^="mldlg_"]').forEach(function(d) { if (d.open) d.close(); });
    }
    var apiParams = (params || ('lang=' + encodeURIComponent(lang))) + '&ua=' + encodeURIComponent(ua);
    if (pageNo && pageNo.match(/^\d+$/)) {
        apiParams = apiParams + "&pageNo=" + encodeURIComponent(pageNo);
    }
    if (window._fdsFavorites) apiParams = apiParams + '&favorites=' + encodeURIComponent(window._fdsFavorites);
    if (window._fdsTrash) apiParams = apiParams + '&trash=' + encodeURIComponent(window._fdsTrash);
    if (window._fdsTaggedMids) apiParams = apiParams + '&tagged=' + encodeURIComponent(window._fdsTaggedMids);
    if (window._fdsSysTagged) apiParams = apiParams + '&sys_tagged=' + encodeURIComponent(window._fdsSysTagged);
    if (window._fdsPin && !window._fdsTrashMode) apiParams = apiParams + '&pin=' + encodeURIComponent(window._fdsPin);
    if (_fdsSortCol && _fdsSortDir) apiParams = apiParams + '&sort_col=' + encodeURIComponent(_fdsSortCol) + '&sort_dir=' + encodeURIComponent(_fdsSortDir);
    if (window._fdsCtrlMode && window._fdsCtrlMode !== 'classic') apiParams = apiParams + '&ctrl=' + encodeURIComponent(window._fdsCtrlMode);

    var _rlDelay = _checkClientRateLimit();
    if (_rlDelay > 0) {
        _showDebounceBar(_rlDelay);
        setTimeout(function() { doSearch(pageNo, scrollTop, noScroll); }, _rlDelay);
        return;
    }
    _apiCallTimes.push(Date.now());
    if (navigator.webdriver) apiParams += '&_wd=1';
    apiParams += '&_cv=120';
    window._fdsCurrentPage = (pageNo && pageNo.match(/^\d+$/)) ? pageNo : '1';
    window._fdsLastApiParams = apiParams;
    window._fdsSearchCalled = true;

    fetch('/api/rows?' + apiParams)
        .then(function(r) {
            if (!r.ok) throw new Error('api error');
            return r.json();
        })
        .then(function(data) {
            // Update table rows (keep header row)
            var table = document.getElementById('frame_table');
            if (table) {
                // Clean up stale gif-players before replacing DOM
                table.querySelectorAll('[id^="inline_div_"]').forEach(function(div) {
                    if (window._gifVisibilityObserver) window._gifVisibilityObserver.unobserve(div);
                    var gif = div.querySelector('[id^="inline_img_"]');
                    if (gif && gif.src && gif.src.startsWith('blob:')) {
                        try { URL.revokeObjectURL(gif.src); } catch(e) {}
                    }
                });
                table.querySelectorAll('[data-mid]').forEach(function(el) {
                    if (window._inlineGifObserver) window._inlineGifObserver.unobserve(el);
                });
                table.querySelectorAll('gif-player').forEach(function(gp) {
                    gp.paused = true;
                    gp._reset();
                });
                var _headerRows = Array.prototype.slice.call(table.querySelectorAll('tr.header'));
                table.innerHTML = '';
                _headerRows.forEach(function(h) { table.appendChild(h); });
                table.insertAdjacentHTML('beforeend', data.tableRows);
            }
            // Update page nav
            var pageNavEl = document.getElementById('fds-page-nav');
            if (pageNavEl) pageNavEl.innerHTML = data.pageNav;
            // Replace dialogs
            document.querySelectorAll('dialog[id^="mdialog_"],dialog[id^="mldlg_"]').forEach(function(d) { if (d.open) d.close(); d.remove(); });
            var oldScript = document.getElementById('fds-dialog-script');
            if (oldScript) oldScript.remove();
            if (data.dialogs) document.body.insertAdjacentHTML('beforeend', data.dialogs);
            if (data.scripts) {
                var s = document.createElement('script');
                s.id = 'fds-dialog-script';
                s.textContent = '(function(){' + data.scripts + '})()';
                document.body.appendChild(s);
            }
            // Update chart
            if (window._fdsChart && data.chartLabels && data.chartData) {
                window._fdsChart.data.labels = data.chartLabels;
                window._fdsChart.data.datasets[0].data = data.chartData;
                window._fdsChart.update();
            }
            if (data.chartLabels && data.chartData) {
                var _isAll = !character_name && !category && !start_up && !recovery && !hit && !block;
                window._updateSidebarCounts(data.chartLabels, data.chartData, _isAll ? '∀' : data.chartTotal);
            }
            window._fdsTotalCount = data.chartTotal != null ? data.chartTotal : null;
            // Update URL without reload
            _fdsCurrentLang = lang;
            history.pushState(null, '', newUrl);
            var _scrollHandledByTemplate = window._fabScrollToTable || window._fabScrollToLast;
            if (window._onSearchDone) window._onSearchDone({character_name:character_name,category:category,start_up_op:start_up_op,start_up:start_up,recovery_op:recovery_op,recovery:recovery,hit_op:hit_op,hit:hit,block_op:block_op,block:block});
            if (ua === 'mobile' || ua === 'mobile_list') {
                if (pageNo) {
                    if (!_scrollHandledByTemplate) {
                        if (window._disableSnap) window._disableSnap(1200);
                        var _sEl = document.querySelector('[style*="position: sticky"]') || document.querySelector('[style*="position:sticky"]');
                        var _sH = _sEl ? _sEl.offsetHeight : 44;
                        var _tfrEl = document.getElementById('fds-tag-filter-row');
                        var _tfrH = (_tfrEl && !_tfrEl.hidden) ? _tfrEl.offsetHeight : 0;
                        var _tw = document.getElementById('table-wrap');
                        if (_tw) {
                            var _destY = _tw.getBoundingClientRect().top + window.scrollY - _sH - _tfrH;
                            window.scrollTo({ top: Math.max(0, _destY), behavior: 'smooth' });
                        }
                    }
                } else if (scrollTop) {
                    window.scroll({ top: 0, behavior: 'smooth' });
                }
            } else {
                if (pageNo) {
                    var tw2 = document.getElementById('table-wrap');
                    if (tw2) tw2.scrollIntoView({ behavior: 'smooth' });
                } else if (!noScroll) {
                    window.scroll({ top: 0, behavior: 'smooth' });
                }
            }
            // 広告リフレッシュ: N回検索ごとにフルリロード（ページ送り・ゴミ箱トグル除外）
            if (!pageNo && !skipAdCount && !window._fdsTrashMode) {
                _fdsAdRefreshCount++;
                if (_fdsAdRefreshCount % _FDS_AD_REFRESH_EVERY === 0) {
                    var _adLang = document.getElementById('language') ? document.getElementById('language').value : '';
                    window.location.href = '/' + (_adLang ? '?lang=' + encodeURIComponent(_adLang) : '');
                }
            }
        })
        .catch(function() {
            if ((window.location.pathname + window.location.search) !== newUrl) {
                window.location.href = newUrl;
            }
        });

    return false;
}

window.addEventListener('popstate', function() { window.location.reload(); });

document.addEventListener('click', function(e) {
    var a = e.target.closest('#frame_table a[href]');
    if (!a) return;
    var href = a.getAttribute('href');
    if (!href || !href.startsWith('/?')) return;
    e.preventDefault();
    var url;
    try { url = new URL(a.href); } catch(err) { return; }
    ['lang', 'character_name', 'category', 'start_up', 'start_up_op', 'recovery', 'recovery_op', 'hit', 'hit_op', 'block', 'block_op'].forEach(function(k) {
        var el = document.getElementById(k);
        if (el) el.value = url.searchParams.get(k) || '';
    });
    doSearch(null, true);
});

var _fdsCurrentLang = '';

function _updateCondStyles() {
    ['character_name', 'category'].forEach(function(id) {
        var sel = document.getElementById(id);
        if (sel) {
            sel.style.borderColor = sel.value ? 'var(--fds-link-color)' : '';
            sel.style.boxShadow = sel.value ? 'var(--fds-focus-ring)' : '';
            sel.style.backgroundColor = '';
            sel.style.color = '';
        }
    });
    ['start_up', 'recovery', 'hit', 'block'].forEach(function(id) {
        var inp = document.getElementById(id);
        var op = document.getElementById(id + '_op');
        if (inp) {
            inp.style.borderColor = inp.value ? 'var(--fds-link-color)' : '';
            inp.style.boxShadow = inp.value ? 'var(--fds-focus-ring)' : '';
            inp.style.backgroundColor = '';
            inp.style.color = '';
        }
        if (op) {
            op.style.borderColor = op.value ? 'var(--fds-link-color)' : '';
            op.style.boxShadow = op.value ? 'var(--fds-focus-ring)' : '';
            op.style.backgroundColor = '';
            op.style.color = '';
        }
    });
}

document.addEventListener('click', function(e) {
    var a = e.target.closest('a[href]');
    if (!a) return;
    if (e.target.closest('#frame_table')) return;
    var href = a.getAttribute('href');
    if (!href || !href.startsWith('/?')) return;

    var q = new URLSearchParams(href.slice(2));

    // 言語変更は全リロード
    var currentLang = document.getElementById('language').value;
    var newLang = q.get('lang') || currentLang;
    if (newLang !== currentLang) return;

    e.preventDefault();

    // フォームを一旦リセットしてリンクのパラメータで上書き
    ['character_name', 'category', 'start_up', 'start_up_op',
     'recovery', 'recovery_op', 'hit', 'hit_op', 'block', 'block_op'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.value = q.has(id) ? q.get(id) : '';
    });
    _updateCondStyles();

    doSearch(q.get('pageNo') || undefined);
});

window.toggleFdsChart = function() {
    var body = document.getElementById('fds-chart-body');
    var arrow = document.getElementById('fds-chart-toggle-arrow');
    if (!body) return;
    var open = body.dataset.open !== '1';
    body.dataset.open = open ? '1' : '0';
    if (arrow) arrow.textContent = open ? '▼' : '▶';
    if (open) {
        body.style.maxHeight = body.scrollHeight + 'px';
    } else {
        body.style.maxHeight = body.scrollHeight + 'px';
        requestAnimationFrame(function() { requestAnimationFrame(function() { body.style.maxHeight = '0'; }); });
    }
    try { localStorage.setItem('fds_chart_open', open ? '1' : '0'); } catch(e) {}
};

window._updateSidebarCounts = function(labels, data, total) {
    var m = {};
    if (labels && data) labels.forEach(function(n, i) { m[n] = data[i] || 0; });
    var tot = total || 0;
    document.querySelectorAll('#char-list li[data-charname]').forEach(function(li) {
        var el = li.querySelector('.fds-char-count');
        if (!el) return;
        var c = m.hasOwnProperty(li.dataset.charname) ? m[li.dataset.charname] : 0;
        el.innerHTML = '<span><b>' + c + '</b></span>';
        el.classList.toggle('nz', c > 0);
    });
};

function _applySortState(col, dir) {
    _fdsSortCol = col;
    _fdsSortDir = dir;
    try {
        if (col && dir) { localStorage.setItem('fds_sort_col', col); localStorage.setItem('fds_sort_dir', dir); }
        else { localStorage.removeItem('fds_sort_col'); localStorage.removeItem('fds_sort_dir'); }
    } catch(e) {}
    document.querySelectorAll('th[data-sort-col]').forEach(function(th) {
        th.dataset.sortActive = (th.dataset.sortCol === col && dir) ? dir : '';
    });
}

document.addEventListener('click', function(e) {
    var th = e.target.closest('th[data-sort-col]');
    if (!th) return;
    var col = th.dataset.sortCol;
    var nextDir;
    if (_fdsSortCol !== col) { nextDir = 'asc'; }
    else if (_fdsSortDir === 'asc') { nextDir = 'desc'; }
    else { col = null; nextDir = null; }
    _applySortState(col, nextDir);
    clearTimeout(_fdsSortTimer);
    _fdsSortTimer = setTimeout(function() { doSearch(); }, 300);
});

window.addEventListener('load', function() {
    var el = document.getElementById('language');
    _fdsCurrentLang = el ? el.value : '';
    if (window._fdsChartInitData && !window._fdsSearchCalled) {
        var d = window._fdsChartInitData;
        var _urlP = new URLSearchParams(location.search);
        var _initAll = !_urlP.get('character_name') && !_urlP.get('category') &&
                       !_urlP.get('start_up') && !_urlP.get('recovery') &&
                       !_urlP.get('hit') && !_urlP.get('block');
        window._updateSidebarCounts(d.labels, d.data, _initAll ? '∀' : d.total);
    }
    if (window._onSearchDone) {
        var p = {};
        ['character_name','category','start_up','start_up_op','recovery','recovery_op','hit','hit_op','block','block_op'].forEach(function(k) {
            var fe = document.getElementById(k);
            if (fe && fe.value) p[k] = fe.value;
        });
        window._onSearchDone(p);
    }
    if (_fdsSortCol && _fdsSortDir) {
        _applySortState(_fdsSortCol, _fdsSortDir);
        doSearch();
    }
    (function() {
        var body = document.getElementById('fds-chart-body');
        if (!body) return;
        var open = false;
        try { open = localStorage.getItem('fds_chart_open') === '1'; } catch(e) {}
        body.dataset.open = open ? '1' : '0';
        var arrow = document.getElementById('fds-chart-toggle-arrow');
        if (arrow) arrow.textContent = open ? '▼' : '▶';
        if (open) {
            body.style.maxHeight = body.scrollHeight + 'px';
        }
    })();
});

jQuery(function ($) {
    $('#contactForm').submit(function (event) {
        // HTMLでの送信をキャンセル
        event.preventDefault();


        // 操作対象のフォーム要素を取得
        var $form = $(this);
        if (!$('#msg').val()) {
            return;
        }
        // 送信ボタンを取得
        // （後で使う: 二重送信を防止する。）
        var $button = $form.find('button');

        // 送信
        $.ajax({
            url: $form.attr('action'),
            type: $form.attr('method'),
            data: $form.serialize(),
            timeout: 10000,  // 単位はミリ秒

            // 送信前
            beforeSend: function (xhr, settings) {
                // ボタンを無効化し、二重送信を防止
                $button.attr('disabled', true);
            },
            // 応答後
            complete: function (xhr, textStatus) {
                // ボタンを有効化し、再送信を許可
                $button.attr('disabled', false);
            },

            // 通信成功時の処理
            success: function (result) {
                // 入力値を初期化
                $form[0].reset();

                //成功時の処理
                const lang = document.getElementById("language").value;
                if (result.result === 'success') {
                    if (lang === 'ja-jp') {
                        $('#result').text("メッセージを送信しました。");
                    } else {
                        $('#result').text("Your message has been sent. Thank you for contacting us.");
                    }
                } else {
                    if (lang === 'ja-jp') {
                        $('#result').text("メッセージの送信に失敗しました。");
                    } else {
                        $('#result').text("An error occurred.");
                    }
                }
            },

            // 通信失敗時の処理
            error: function (xhr, textStatus, error) { }
        });
    });

});
